package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/** A person on a sheet. Mutable so an Apply step can change it in place. */
public class Person {

    private final long id;
    private final String sheetId;
    private String name;
    private String grade;
    private List<GradeFrom> grades = List.of();
    private long version;
    private Statements statements = Statements.NONE;
    private LocalDate retiredFrom;
    private List<HoldSpan> holds = List.of();
    private List<RetirementSpan> retirements = List.of();
    private List<String> patrons = List.of();
    private List<String> aliases = List.of();
    private List<SnapshotLine> snapshots = List.of();
    private List<StatementLine> statementLines = List.of();
    private Integer terms;
    private String contact;
    private String tags;

    private String origin;

    public Person(long id, String sheetId, String name, String grade, long version) {
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        this.grade = grade;
        this.version = version;
    }

    public long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    /** The grade in force on the sheet's today. */
    public String getGrade() {
        return grade;
    }

    public void setGrade(String grade) {
        this.grade = grade;
    }

    /** The grades the person was given, each from its from-date (the first from the beginning of time). */
    public List<GradeFrom> getGrades() {
        return grades;
    }

    public void setGrades(List<GradeFrom> grades) {
        this.grades = grades;
    }

    /** The grade in force on the date: the one with the latest from-date on or before it, none counting as the earliest. */
    public String gradeOn(LocalDate on) {
        GradeFrom found = null;
        for (GradeFrom g : grades) {
            if (g.from() != null && g.from().isAfter(on)) {
                continue;
            }
            if (found == null || (g.from() != null && (found.from() == null || g.from().isAfter(found.from())))) {
                found = g;
            }
        }
        return found == null ? grade : found.grade();
    }

    /** The person's own terms in days; null when they have none. */
    public Integer getTerms() {
        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    /** The person's contact, trimmed and lower-cased; null when they have none. */
    public String getContact() {
        return contact;
    }

    public void setContact(String contact) {
        this.contact = contact;
    }

    /** The person's tags, sorted and joined by commas; null when they have none. */
    public String getTags() {
        return tags;
    }

    public void setTags(String tags) {
        this.tags = tags;
    }

    /** The sheet the person was transferred from; null when they were not transferred in. */
    public String getOrigin() {
        return origin;
    }

    public void setOrigin(String origin) {
        this.origin = origin;
    }

    public long getVersion() {
        return version;
    }

    public void setVersion(long version) {
        this.version = version;
    }

    /** The person's statements: how many, and the last one's due-total and date. */
    public Statements getStatements() {
        return statements;
    }

    public void setStatements(Statements statements) {
        this.statements = statements;
    }

    /** The date the person is retired from; null when not retired. Set at all, the person counts as retired. */
    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    public boolean isRetired() {
        return retiredFrom != null;
    }

    /** Whether the person's retirement date is reached on the date: from then their OPEN and PENDING claims, unless a
     *  statement binds them, count in no live total, as a hold's would. */
    public boolean retiredOn(LocalDate on) {
        return retiredFrom != null && !on.isBefore(retiredFrom);
    }

    /** The person's past retirements, each from its from-date to the day they were unretired, in the order kept. */
    public List<RetirementSpan> getRetirements() {
        return retirements;
    }

    public void setRetirements(List<RetirementSpan> retirements) {
        this.retirements = retirements;
    }

    /** Whether a claim dated then is refused: after the current retirement's date, or strictly between a past
     *  retirement's from-date and the day it ended. */
    public boolean retiredClaimDate(LocalDate date) {
        return (retiredFrom != null && date.isAfter(retiredFrom))
                || retirements.stream().anyMatch(r -> r.refuses(date));
    }

    /** Whether the person has any hold. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** The person's holds, in the order they were added. */
    public List<HoldSpan> getHolds() {
        return holds;
    }

    public void setHolds(List<HoldSpan> holds) {
        this.holds = holds;
    }

    /** Whether a hold covers the date: the person's OPEN and PENDING claims dated then, unless a statement binds them,
     *  count in no live total. */
    public boolean heldOn(LocalDate on) {
        return holds.stream().anyMatch(h -> h.covers(on));
    }

    /** The names of the person's patrons, sorted. */
    public List<String> getPatrons() {
        return patrons.stream().sorted().toList();
    }

    /** The names of the person's patrons, in the order they were named. */
    public List<String> getPatronsNamed() {
        return patrons;
    }

    /** Sets the names of the person's patrons, in the order they were named. */
    public void setPatrons(List<String> patrons) {
        this.patrons = patrons;
    }

    /**
     * The person's patrons with their shares, sorted by name: 100.00 split equally in the order they were named, each
     * share rounded half to even to two decimals, the remainder (100.00 less the shares added up) to the first named.
     */
    public List<PatronShare> getPatronShares() {
        if (patrons.isEmpty()) {
            return List.of();
        }
        BigDecimal hundred = new BigDecimal("100.00");
        BigDecimal each = hundred.divide(BigDecimal.valueOf(patrons.size()), 2, RoundingMode.HALF_EVEN);
        BigDecimal first = hundred.subtract(each.multiply(BigDecimal.valueOf(patrons.size() - 1)));
        List<PatronShare> shares = new ArrayList<>();
        for (int i = 0; i < patrons.size(); i++) {
            shares.add(new PatronShare(patrons.get(i), i == 0 ? first : each));
        }
        shares.sort(Comparator.comparing(PatronShare::name));
        return shares;
    }

    private boolean clashing;

    /** Whether the person's name or an alias of theirs is used, as a name or alias, on another sheet of their tree. */
    public boolean isClashing() {
        return clashing;
    }

    public void setClashing(boolean clashing) {
        this.clashing = clashing;
    }

    /** The person's aliases, sorted as names are compared. */
    public List<String> getAliases() {
        return aliases;
    }

    public void setAliases(List<String> aliases) {
        this.aliases = aliases;
    }

    /** The person's snapshot lines, oldest first. */
    public List<SnapshotLine> getSnapshots() {
        return snapshots;
    }

    public void setSnapshots(List<SnapshotLine> snapshots) {
        this.snapshots = snapshots;
    }

    /** The person's statement lines, one per statement still standing, oldest first. */
    public List<StatementLine> getStatementLines() {
        return statementLines;
    }

    public void setStatementLines(List<StatementLine> statementLines) {
        this.statementLines = statementLines;
    }
}
package net.officefloor.hq.app.access;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.person.Person;

/**
 * A sheet's dated settings: each key's value in force on a date is the one with the latest from-date on or before it;
 * before every from-date, the key's starting value (see {@link Setting#starting}).
 */
public record DatedSettings(List<DatedValue> values) {

    /** The key's value in force on the date; null when blank. */
    public String on(String key, LocalDate date) {
        DatedValue found = null;
        for (DatedValue v : values) {
            if (v.key().equals(key) && !v.from().isAfter(date) && (found == null || v.from().isAfter(found.from()))) {
                found = v;
            }
        }
        return found == null ? Setting.starting(key) : found.value();
    }

    /** The floor in force on the date: the least a claim's live due may be. */
    public BigDecimal floor(LocalDate date) {
        return new BigDecimal(orStarting(Setting.FLOOR, date)).setScale(2);
    }

    /** The rounding mode in force on the date; null when there is none (the policy date decides). */
    public java.math.RoundingMode rounding(LocalDate date) {
        String value = on(Setting.ROUNDING, date);
        if (Setting.ROUNDING_HALF_UP.equals(value)) {
            return java.math.RoundingMode.HALF_UP;
        }
        return Setting.ROUNDING_HALF_EVEN.equals(value) ? java.math.RoundingMode.HALF_EVEN : null;
    }

    /** The late percent in force on the date. */
    public BigDecimal latePct(LocalDate date) {
        return new BigDecimal(orStarting(Setting.LATE_PCT, date)).setScale(2);
    }

    /** The terms of the grade in force on the date: its own (setting terms-<grade>), else the sheet's. */
    public int terms(String grade, LocalDate date) {
        String value = grade == null ? null : on(Setting.TERMS_OF_GRADE + grade, date);
        return Integer.parseInt(value == null ? orStarting(Setting.TERMS, date) : value);
    }

    /** The terms in force on the date for the person: their own, else their grade's on that date, else the sheet's. */
    public int terms(Person person, LocalDate date) {
        if (person != null && person.getTerms() != null) {
            return person.getTerms();
        }
        return terms(person == null ? null : person.gradeOn(date), date);
    }

    /** The grace of the grade in force on the date (setting grace-<grade>): the days past its due-by a claim goes overdue; 0 while blank. */
    public int grace(String grade, LocalDate date) {
        String value = grade == null ? null : on(Setting.GRACE_OF_GRADE + grade, date);
        return value == null ? 0 : Integer.parseInt(value);
    }

    /** The clerk limit in force on the date; null when there is none. */
    public BigDecimal clerkLimit(LocalDate date) {
        String value = on(Setting.CLERK_LIMIT, date);
        return value == null ? null : new BigDecimal(value);
    }

    /** The proof threshold in force on the date; null when there is none. */
    public BigDecimal proofThreshold(LocalDate date) {
        String value = on(Setting.PROOF_THRESHOLD, date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    /** The proof threshold in force on the date for a claim of the grade: the grade's own (setting proof-threshold-<grade>) when set, else the sheet's; null when there is none. */
    public BigDecimal proofThreshold(String grade, LocalDate date) {
        String value = grade == null ? null : on(Setting.PROOF_THRESHOLD_OF_GRADE + grade, date);
        return value == null ? proofThreshold(date) : new BigDecimal(value).setScale(2);
    }

    /** The note threshold in force on the date; null when there is none. */
    public BigDecimal noteThreshold(LocalDate date) {
        String value = on(Setting.NOTE_THRESHOLD, date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    /** The review threshold in force on the date; null when there is none. */
    public BigDecimal reviewThreshold(LocalDate date) {
        String value = on(Setting.REVIEW_THRESHOLD, date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    /** The cap in force on the date: the most a person's due-total may be; null when there is none. */
    public BigDecimal cap(LocalDate date) {
        String value = on(Setting.CAP, date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    private String orStarting(String key, LocalDate date) {
        String value = on(key, date);
        return value == null ? Setting.starting(key) : value;
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.access.SettingRepository;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Adds the claim (date blank: the sheet's entry date, else its today), due by the terms-th business day after its date (skipping Saturdays, Sundays and the sheet's holidays), with the terms in force on that date for its person (their own, else their grade's on that date, else the sheet's) fixed from now on; a late entry when that due-by is in a soft-closed period. */
public class BuildClaim {
    public void build(@Val Person person, @Val ClaimInput input, ClaimRepository repository,
            SheetRepository sheets, SettingRepository settings, PeriodRepository periods, HolidayRepository holidays, Out<Claim> claim) {
        LocalDate date = input.date() != null ? input.date()
                : settings.entryDate(person.getSheetId(), sheets.today(person.getSheetId()));
        Claim added = repository.insert(person.getSheetId(), person.getId(), input.amount(), date, input.note(),
                input.corrects(), input.ref(), input.tags(), terms(person, date, settings));
        if (periods.softClosedOn(person.getSheetId(), added.getDueBy())) {
            repository.markLate(added);
        }
        claim.set(added);
    }

    /** The terms a claim of the person dated {@code date} is fixed with: those in force then for them. */
    static int terms(Person person, LocalDate date, SettingRepository settings) {
        return settings.dated(person.getSheetId()).terms(person, date);
    }

    /**
     * The due-by a claim of the person dated {@code date} would have: the terms-th business day after its date, by the
     * sheet's holidays as they stand now.
     */
    static LocalDate dueBy(Person person, LocalDate date, SettingRepository settings, HolidayRepository holidays) {
        return holidays.dueBy(person.getSheetId(), date, terms(person, date, settings));
    }
}
package net.officefloor.hq.app.person;

import java.sql.PreparedStatement;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The people on each sheet; ids are assigned in the order people are added, and each has a place in the sheet's
 *  list (new people at the end, moved by swapping with a neighbour). */
@Repository
public class PersonRepository {

    /** A person's columns, with the grade in force on the sheet's today, their statement count and their last statement's due-total and date. */
    private static final String COLUMNS = "p.id, p.sheet_id, p.name, p.version, p.retired_from, p.terms, p.contact, p.tags, p.origin,"
            + " (SELECT g.grade FROM person_grade g WHERE g.person_id = p.id AND (g.from_date IS NULL"
            + " OR g.from_date <= (SELECT t.today FROM sheet t WHERE t.id = p.sheet_id))"
            + " ORDER BY g.from_date DESC NULLS LAST LIMIT 1) AS grade,"
            + " (SELECT COUNT(*) FROM statement s WHERE s.person_id = p.id) AS statement_count,"
            + " (SELECT s.due_total FROM statement s WHERE s.person_id = p.id ORDER BY s.id DESC LIMIT 1) AS stated_total,"
            + " (SELECT s.taken_on FROM statement s WHERE s.person_id = p.id ORDER BY s.id DESC LIMIT 1) AS statement_date";

    private static final RowMapper<Person> ROW = (rs, n) -> {
        Person person = new Person(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"),
                rs.getString("grade"), rs.getLong("version"));
        person.setStatements(new Statements(rs.getInt("statement_count"), rs.getBigDecimal("stated_total"),
                rs.getObject("statement_date", LocalDate.class)));
        person.setRetiredFrom(rs.getObject("retired_from", LocalDate.class));
        person.setTerms(rs.getObject("terms", Integer.class));
        person.setContact(rs.getString("contact"));
        person.setTags(rs.getString("tags"));
        person.setOrigin(rs.getString("origin"));
        return person;
    };

    private static final RowMapper<GradeFrom> GRADE = (rs, n) -> new GradeFrom(rs.getString("grade"),
            rs.getObject("from_date", LocalDate.class));

    static final String CHANGED = "Someone else has saved this person since you opened it; the form now shows their changes";

    public static final String NAME_TAKEN = "That name is already in use on this sheet or another sheet of its tree";

    static final String CONTACT_TAKEN = "That contact is already another person's on this sheet";

    private final JdbcTemplate jdbc;

    public PersonRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's people, in list order. */
    public List<Person> list(String sheetId) {
        return withPatrons(sheetId, jdbc.query(
                "SELECT " + COLUMNS + " FROM person p WHERE p.sheet_id = ? ORDER BY p.list_position, p.id", ROW, sheetId));
    }

    /**
     * Swap the person with the one above (up) or below them in the sheet's list; answers the person's new place in
     * the list, counting from 1, or null (nothing written) when there is no one there to swap with.
     */
    public Integer move(Person person, boolean up) {
        String sheetId = person.getSheetId();
        List<Long> order = jdbc.queryForList(
                "SELECT id FROM person WHERE sheet_id = ? ORDER BY list_position, id", Long.class, sheetId);
        int at = order.indexOf(person.getId());
        int to = up ? at - 1 : at + 1;
        if (at < 0 || to < 0 || to >= order.size()) {
            return null;
        }
        java.util.Collections.swap(order, at, to);
        // Renumber the whole list, so the swap holds even where positions were equal.
        for (int i = 0; i < order.size(); i++) {
            jdbc.update("UPDATE person SET list_position = ? WHERE id = ?", i + 1, order.get(i));
        }
        return to + 1;
    }

    public Person find(String sheetId, long id) {
        return withPatrons(sheetId,
                jdbc.query("SELECT " + COLUMNS + " FROM person p WHERE p.sheet_id = ? AND p.id = ?", ROW, sheetId, id))
                .stream().findFirst().orElse(null);
    }

    /** The person on the sheet with this name or alias, ignoring case and surrounding spaces; null when none. */
    public Person findByName(String sheetId, String name) {
        return withPatrons(sheetId, jdbc.query(
                "SELECT " + COLUMNS + " FROM person p WHERE p.sheet_id = ? AND (p.name_key = LOWER(TRIM(?))"
                        + " OR p.id IN (SELECT a.person_id FROM person_alias a WHERE a.sheet_id = ? AND a.alias_key = LOWER(TRIM(?))))",
                ROW, sheetId, name, sheetId, name)).stream().findFirst().orElse(null);
    }

    /** Whether another person on the sheet has this name, or anyone on the sheet has it as an alias, or anyone on
     *  another sheet of its tree (see {@link #treeOf}) but that person has it as a name or alias, ignoring case and
     *  surrounding spaces. */
    public boolean nameTaken(String sheetId, String name, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(TRIM(?)) AND id <> ?",
                Integer.class, sheetId, name, exceptId == null ? -1L : exceptId);
        return (n != null && n > 0) || aliasTaken(sheetId, name) || usedInTree(sheetId, name, exceptId);
    }

    /** Whether anyone (but that person) on another sheet of the sheet's tree has this name or alias, ignoring case and
     *  surrounding spaces. */
    public boolean usedInTree(String sheetId, String name, Long exceptId) {
        java.util.Set<String> key = java.util.Set.of(name.trim().toLowerCase());
        return !java.util.Collections.disjoint(namesInTree(sheetId, exceptId), key);
    }

    /** Whether the person's name or any of their aliases is used, as a name or alias, on another sheet of their tree. */
    public boolean clashing(Person person) {
        return clashing(person, namesInTree(person.getSheetId(), person.getId()));
    }

    static boolean clashing(Person person, java.util.Set<String> used) {
        if (used.contains(person.getName().trim().toLowerCase())) {
            return true;
        }
        return person.getAliases().stream().anyMatch(a -> used.contains(a.trim().toLowerCase()));
    }

    /** The names and aliases (lower case, trimmed) of everyone, but that person, on the other sheets of the sheet's tree. */
    public java.util.Set<String> namesInTree(String sheetId, Long exceptId) {
        java.util.Set<String> found = new java.util.HashSet<>();
        long except = exceptId == null ? -1L : exceptId;
        for (String other : treeOf(sheetId)) {
            found.addAll(jdbc.queryForList("SELECT name_key FROM person WHERE sheet_id = ? AND id <> ?", String.class,
                    other, except));
            found.addAll(jdbc.queryForList("SELECT alias_key FROM person_alias WHERE sheet_id = ? AND person_id <> ?",
                    String.class, other, except));
        }
        return found;
    }

    /** The other sheets of the sheet's tree, among the sheets that exist: its parent, theirs and so on up, and its
     *  children, theirs and so on down (each once, the sheet itself never among them). */
    public List<String> treeOf(String sheetId) {
        java.util.Set<String> seen = new java.util.LinkedHashSet<>(List.of(sheetId));
        for (String at = parentOf(sheetId); at != null && seen.add(at); at = parentOf(at)) {
        }
        java.util.Deque<String> todo = new java.util.ArrayDeque<>(List.of(sheetId));
        while (!todo.isEmpty()) {
            for (String child : jdbc.queryForList("SELECT sheet_id FROM sheet_setting WHERE setting_key = 'parent'"
                    + " AND setting_value = ? ORDER BY sheet_id", String.class, todo.poll())) {
                if (seen.add(child)) {
                    todo.add(child);
                }
            }
        }
        seen.remove(sheetId);
        return seen.stream().filter(s -> jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, s) > 0)
                .toList();
    }

    private String parentOf(String sheetId) {
        return jdbc.query("SELECT setting_value FROM sheet_setting WHERE sheet_id = ? AND setting_key = 'parent'",
                (rs, n) -> rs.getString(1), sheetId).stream().filter(v -> v != null && !v.isBlank()).findFirst()
                .orElse(null);
    }

    /** Whether anyone on the sheet has this alias, ignoring case and surrounding spaces. */
    public boolean aliasTaken(String sheetId, String alias) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person_alias WHERE sheet_id = ? AND alias_key = LOWER(TRIM(?))",
                Integer.class, sheetId, alias);
        return n != null && n > 0;
    }

    /** Give the person the alias (trimmed); false (nothing written) when the sheet has it as an alias already. */
    public boolean addAlias(Person person, String alias) {
        try {
            return jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) SELECT ?, ?, ? WHERE NOT EXISTS"
                    + " (SELECT 1 FROM person_alias WHERE sheet_id = ? AND alias_key = LOWER(TRIM(?)))",
                    person.getSheetId(), person.getId(), alias, person.getSheetId(), alias) == 1;
        } catch (DuplicateKeyException e) {
            return false;
        }
    }

    /** Whether another person on the sheet has this contact; false for no contact (null). */
    public boolean contactTaken(String sheetId, String contact, Long exceptId) {
        if (contact == null) {
            return false;
        }
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM person WHERE sheet_id = ? AND contact = ? AND id <> ?",
                Integer.class, sheetId, contact, exceptId == null ? -1L : exceptId);
        return n != null && n > 0;
    }

    /** Add the person, their grade in force from the beginning of time. */
    public Person insert(String sheetId, String name, String grade) {
        return insert(sheetId, name, grade, null, null);
    }

    /** Add the person with their own terms and contact (null for none), their grade in force from the beginning of time. */
    public Person insert(String sheetId, String name, String grade, Integer terms, String contact) {
        return insert(sheetId, name, grade, terms, contact, null);
    }

    /** Add the person with their own terms, contact and tags (null for none), their grade in force from the beginning
     *  of time; their tags are noted as used on the sheet. */
    public Person insert(String sheetId, String name, String grade, Integer terms, String contact, String tags) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
