package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class BuildPerson {
    public void build(@Val SheetResponse sheet, @Val PersonRequest request, PersonRepository repository,
            Out<Person> person) {
        person.set(repository.insert(sheet.id(), request.name(), request.grade(), request.termsDays(),
                request.contactOrNull(), request.tagsOrNull()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

public class RecordPersonAdded {
    public void record(@Val Person person, @Val ChangedBy by, Audit audit) {
        audit.record("PERSON_ADDED sheet=" + person.getSheetId() + " by=" + by.name() + " name=" + person.getName()
                + " grade=" + person.getGrade() + (person.getTerms() == null ? "" : " terms=" + person.getTerms())
                + (person.getContact() == null ? "" : " contact=" + person.getContact()));
    }
}
            return;
        }
        ApplyPerson apply = new ApplyPerson();
        RecordPersonEdited record = new RecordPersonEdited();
        int changed = 0;
        for (Person person : people.list(sheet.id())) {
            if (!bulk.ids().contains(person.getId())) {
                continue;
            }
            PersonRequest request = new PersonRequest(person.getName(), bulk.grade(), by.name(), person.getVersion(),
                    bulk.from(), person.getTerms() == null ? "" : String.valueOf(person.getTerms()),
                    person.getContact() == null ? "" : person.getContact(),
                    person.getTags() == null ? "" : person.getTags());
            RollupSnapshot before = rollup.snapshot(sheet.id());
            TermsEdit[] terms = new TermsEdit[1];
            ContactEdit[] contact = new ContactEdit[1];
            apply.apply(request, person, people, sheets, value -> terms[0] = value, value -> contact[0] = value);
            record.record(person, by, terms[0], contact[0], audit);
            rollup.record(sheet.id(), before, by);
            changed++;
        }
        result.set(new BulkGradeResponse(changed));
    }
}
                }
            }
            matched.add(person);
        }
        LocalDate today = sheets.today(sheet.id());
        int added = 0;
        int updated = 0;
        for (int i = 0; i < imported.people().size(); i++) {
            PersonRequest request = imported.people().get(i);
            Person person = matched.get(i);
            RollupSnapshot before = rollup.snapshot(sheet.id());
            if (person == null) {
                person = repository.insert(sheet.id(), request.name(), request.grade(), request.termsDays(),
                        request.contactOrNull());
                new RecordPersonAdded().record(person, by, audit);
                added++;
            } else {
                PersonRequest edit = edit(request, person);
                Integer termsBefore = person.getTerms();
                String contactBefore = person.getContact();
                person.setTerms(edit.termsDays());
                person.setContact(edit.contactOrNull());
                if (!repository.update(person)) {
                    throw new ConflictException(PersonRepository.CHANGED);
                }
                repository.giveGrade(person, edit.grade(), today, today);
                new RecordPersonEdited().record(person, by,
                        new TermsEdit(!Objects.equals(termsBefore, person.getTerms())),
                        new ContactEdit(!Objects.equals(contactBefore, person.getContact())), audit);
                updated++;
            }
            rollup.record(sheet.id(), before, by);
        }
        response.set(new ImportPeopleResponse(added, updated));
    }

    /** The line as the form's edit of the person: their name kept, and their terms and contact kept when blank. */
    private static PersonRequest edit(PersonRequest request, Person person) {
        String terms = request.termsDays() != null ? request.terms()
                : person.getTerms() == null ? "" : String.valueOf(person.getTerms());
        String contact = request.contactOrNull() != null ? request.contact()
                : person.getContact() == null ? "" : person.getContact();
        return new PersonRequest(person.getName(), request.grade(), request.by(), person.getVersion(), "", terms,
                contact, person.getTags() == null ? "" : person.getTags());
    }
}
